import { validateMnemonic, wordlists } from 'bip39';

// Match the languages supported by the node's mnemonic generator.
const supportedWordlists = [
  wordlists.chinese_simplified,
  wordlists.chinese_traditional,
  wordlists.english,
  wordlists.french,
  wordlists.italian,
  wordlists.japanese,
  wordlists.korean,
  wordlists.spanish,
];

export default function mnemonicWarning(mnemonic) {
  try {
    // Assessment only: the restore request must retain the original input.
    const normalized = mnemonic.normalize('NFKD');
    const words = normalized.split(' ');
    if (![12, 15, 18, 21, 24].includes(words.length)) {
      return 'unrecognized_mnemonic';
    }
    const matchingWordlists = supportedWordlists.filter((wordlist) =>
      words.every((word) => wordlist.includes(word)),
    );
    if (!matchingWordlists.length) {
      return 'unrecognized_mnemonic';
    }
    return matchingWordlists.some((wordlist) => validateMnemonic(normalized, wordlist))
      ? undefined
      : 'checksum_mismatch';
  } catch (error) {
    return 'unrecognized_mnemonic';
  }
}
