import React, { Component, memo } from 'react';
import { Formik, Field, Form } from 'formik';
import { v4 as uuidv4 } from 'uuid';
import { OverlayTrigger, Tooltip } from 'react-bootstrap';
import nodeApi from '../../../api/api';
import customToast from '../../../utils/toast';
import mnemonicWarning from '../../../utils/mnemonicValidation';

const mnemonicWarnings = {
  checksum_mismatch:
    'This phrase does not pass the BIP39 checksum. Check the words and their order. If you intentionally used a legacy or nonstandard phrase, you can continue with it unchanged.',
  unrecognized_mnemonic:
    'This phrase could not be validated using the supported BIP39 wordlists. Check it before continuing, or continue unchanged if it is your intended legacy phrase.',
};

class RestoreWalletForm extends Component {
  uuid = uuidv4();

  mnemonicInput = React.createRef();

  walletRestore = async (values, uuid) => {
    const {
      walletPassword,
      previousDerivationPath: usePre1627KeyDerivation,
      mnemonicPass = '',
    } = values;
    if (!values[`mnemonic${uuid}`] || !String(values[`mnemonic${uuid}`]).trim()) {
      throw Error('Need to set mnemonic');
    }

    return nodeApi.post(
      '/wallet/restore',
      {
        pass: walletPassword || '',
        mnemonicPass: mnemonicPass || '',
        mnemonic: values[`mnemonic${uuid}`],
        usePre1627KeyDerivation,
      },
      {
        headers: {
          api_key: this.props.apiKey,
        },
      },
    );
  };

  handleSubmit = (
    values,
    { setSubmitting, resetForm, setStatus },
    uuid,
    continueWithPhrase = false,
  ) => {
    const phrase = values[`mnemonic${uuid}`];
    const warning = mnemonicWarning(phrase);
    if (phrase && String(phrase).trim() && warning && !continueWithPhrase) {
      setStatus({ mnemonicWarning: warning });
      setSubmitting(false);
      return;
    }

    setSubmitting(true);
    setStatus({ status: 'submitting' });
    this.walletRestore(values, uuid)
      .then(() => {
        resetForm();
        customToast('success', 'Your wallet successfully re-stored');
      })
      .catch((err) => {
        const errMessage = err.data ? err.data.detail : err.message;
        customToast('error', errMessage);
        setSubmitting(false);
      });
  };

  render() {
    const { uuid } = this;

    return (
      <div className="card bg-white p-4 mb-4">
        <h2 className="h5 mb-3">Re-store wallet</h2>
        <Formik
          initialValues={{
            walletPassword: '',
            mnemonicPass: '',
            [`mnemonic${uuid}`]: '',
            previousDerivationPath: false,
          }}
          onSubmit={(values, props) => this.handleSubmit(values, props, uuid)}
        >
          {({ status, isSubmitting, values, setStatus, ...formHelpers }) => (
            <Form
              onChange={() => {
                if (status && status.mnemonicWarning) setStatus(undefined);
              }}
            >
              {status && status.state === 'error' && (
                <div className="alert alert-danger" role="alert">
                  {status.msg}
                </div>
              )}
              {status && status.state === 'success' && (
                <div className="alert alert-success">{status.msg}</div>
              )}
              <div className="form-group">
                <label htmlFor="restore-mnemonic-input">Mnemonic</label>
                <Field
                  name={`mnemonic${uuid}`}
                  innerRef={this.mnemonicInput}
                  type="text"
                  id="restore-mnemonic-input"
                  className="form-control"
                  placeholder="Enter mnemonic"
                  required
                  aria-describedby="restore-mnemonic-note"
                />
                <small id="restore-mnemonic-note" className="form-text text-muted">
                  A valid checksum cannot confirm the intended wallet or mnemonic password.
                </small>
              </div>
              {status && status.mnemonicWarning && (
                <div
                  className="alert alert-warning"
                  role="alert"
                  data-mnemonic-warning={status.mnemonicWarning}
                >
                  <p>{mnemonicWarnings[status.mnemonicWarning]}</p>
                  <button
                    type="button"
                    className="btn btn-secondary mr-2"
                    onClick={() => {
                      setStatus(undefined);
                      this.mnemonicInput.current.focus();
                    }}
                  >
                    Edit phrase
                  </button>
                  <button
                    type="button"
                    className="btn btn-warning"
                    disabled={isSubmitting}
                    onClick={() =>
                      this.handleSubmit(values, { ...formHelpers, setStatus }, uuid, true)
                    }
                  >
                    Continue with this phrase
                  </button>
                </div>
              )}
              <div className="form-group">
                <label htmlFor="restore-wallet-password-input">Wallet password</label>
                <Field
                  name="walletPassword"
                  type="password"
                  id="restore-wallet-password-input"
                  className="form-control"
                  placeholder="Enter wallet password"
                />
              </div>
              <div className="form-group">
                <label htmlFor="restore-mnemonic-password-input">Mnemonic password</label>
                <Field
                  name="mnemonicPass"
                  type="password"
                  id="restore-mnemonic-password-input"
                  className="form-control"
                  placeholder="Enter mnemonic password"
                />
              </div>
              <div className="form-check">
                <label htmlFor="previous-derivation-path">
                  <Field
                    name="previousDerivationPath"
                    type="checkbox"
                    id="previous-derivation-path"
                    className="form-check-input"
                  />
                  Use previous derivation path{' '}
                  <OverlayTrigger
                    placement="top"
                    delay={{ show: 250, hide: 400 }}
                    overlay={(props) => (
                      <Tooltip id="button-tooltip" {...props}>
                        It&apos;s recommended to set it if the original wallet was created by ergo
                        node before v4.0.105.
                      </Tooltip>
                    )}
                  >
                    <a
                      href="https://github.com/ergoplatform/ergo/issues/1627"
                      target="_blank"
                      rel="noopener noreferrer"
                    >
                      (?)
                    </a>
                  </OverlayTrigger>
                </label>
              </div>
              <button type="submit" className="btn btn-primary" disabled={isSubmitting}>
                Send
              </button>
            </Form>
          )}
        </Formik>
      </div>
    );
  }
}

export default memo(RestoreWalletForm);
